at duis aute irure dolor in reprehenderit voluptate velit esse cillum dolore eu fugiat nulla pariatur excepteur sint occaecat cupidatat non proident sunt in culpa qui officia deserunt mollit anim id est laborum'.split(' ');function make(n){let a=[];for(let i=0;i<n;i++)a.push(source[i%source.length]);a[0]=a[0][0].toUpperCase()+a[0].slice(1);return a.join(' ')+'.'}document.getElementById('generate').onclick=()=>{let p=Math.max(1,Math.min(50,+count.value||3)),w=Math.max(5,Math.min(200,+words.value||50));out.textContent=Array.from({length:p},()=>make(w)).join('\n\n')}</script></body></html>